import{_ as l,C as a,c as o,o as r,aj as c,j as t,G as n,a as d,w as h}from"./chunks/framework.Bfdr4H5E.js";const p="/sk/images/Bar-Chart.webp",y="/sk/images/Anatomy-of-candlestick.webp",m="/sk/images/Candlestick-Price-Example.webp",g="/sk/images/Daily-Candlestick-Chart.webp",T=JSON.parse('{"title":"Anatomy of a Candlestick","description":"","frontmatter":{"outline":"deep","prev":{"text":"Trading Chart","link":"/trading-with-pav/trading-chart"},"next":{"text":"Chart Timeframes","link":"/trading-with-pav/chart-Timeframes"}},"headers":[],"relativePath":"trading-with-pav/anatomy-of-a-candlestick.md","filePath":"trading-with-pav/anatomy-of-a-candlestick.md"}'),b={name:"trading-with-pav/anatomy-of-a-candlestick.md"};function u(f,e,k,w,x,C){const i=a("GraphComment"),s=a("ClientOnly");return r(),o("div",null,[e[0]||(e[0]=c('<h1 id="anatomy-of-a-candlestick" tabindex="-1">Anatomy of a Candlestick <a class="header-anchor" href="#anatomy-of-a-candlestick" aria-label="Permalink to &quot;Anatomy of a Candlestick&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Content</p><nav class="table-of-contents"><ul><li><a href="#history-of-the-japanese-candlestick">History of the Japanese Candlestick</a></li><li><a href="#candlestick-anatomy">Candlestick Anatomy</a></li><li><a href="#video">Video</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="history-of-the-japanese-candlestick" tabindex="-1">History of the Japanese Candlestick <a class="header-anchor" href="#history-of-the-japanese-candlestick" aria-label="Permalink to &quot;History of the Japanese Candlestick&quot;">​</a></h2><p>Before we jump in, it is worth spending time to understand in brief the history of the Japanese Candlesticks. As the name suggests, the candlesticks originated from Japan. The earliest use of candlesticks dates back to the 18th century by a Japanese rice merchant named Homma Munehisa.</p><p>Though the candlesticks have been in existence for a long time in Japan, and are probably the oldest form of price analysis, the western world traders were clueless about it. It is believed that sometime around 1980’s a trader named Steve Nison accidentally discovered candlesticks, and he introduced the methodology to the rest of the world. He authored the first-ever book on candlesticks titled “Japanese Candlestick Charting Techniques” which is still a favorite amongst many traders.</p><p>Most of the candlesticks pattern still retains the Japanese names; thus giving an oriental feel to technical analysis.</p><h2 id="candlestick-anatomy" tabindex="-1">Candlestick Anatomy <a class="header-anchor" href="#candlestick-anatomy" aria-label="Permalink to &quot;Candlestick Anatomy&quot;">​</a></h2><p>While in a bar chart the open and the close prices are shown by a tick on the left and the right sides of the bar respectively, however in a candlestick the open and close prices are displayed by a rectangular body.</p><p><img src="'+p+'" alt="Bar Chart.webp"></p><p>In a candlestick chart, candles can be classified as a bullish or bearish candle usually represented by blue/green/white and red/black candles. Needless to say, the colors can be customized to any color of your choice; the technical analysis software allows you to do this. This website has opted for the Green and Red combination to represent bullish and bearish candles, respectively.</p><p>Let us look at the <strong>bullish candle</strong>. The candlestick, like a bar chart, is made of 3 components.</p><ol><li>The Central real body – The real body, rectangular connects the opening and closing price. The opening is at the bottom end, and the closing is at the rectangle’s top end.</li><li>Upper shadow – Connects the high point to the close.</li><li>Lower Shadow – Connects the low point to the open.</li></ol><p>The below image shows the above 3 components of bullish candle to the left.</p><p><img src="'+y+'" alt="Anatomy of candlestick.webp"></p><p>Likewise, the <strong>bearish candle</strong> shown above to the left also has 3 components:</p><ol><li>The Central real body – The real body, rectangular which connects the opening and closing price. However, the opening is at the top end, and the closing is at the rectangle’s bottom end.</li><li>Upper shadow – Connects the high point to the open.</li><li>Lower Shadow – Connects the Low point to the close.</li></ol><p>This is best understood with an example. Let us assume the prices as follows.</p><table tabindex="0"><thead><tr><th style="text-align:center;">OHCL Data</th><th style="text-align:center;">Bullish Candle</th><th style="text-align:center;">Bearish Candle</th></tr></thead><tbody><tr><td style="text-align:center;">Open</td><td style="text-align:center;">10</td><td style="text-align:center;">20</td></tr><tr><td style="text-align:center;">High</td><td style="text-align:center;">23</td><td style="text-align:center;">23</td></tr><tr><td style="text-align:center;">Low</td><td style="text-align:center;">8</td><td style="text-align:center;">8</td></tr><tr><td style="text-align:center;">Close</td><td style="text-align:center;">20</td><td style="text-align:center;">10</td></tr></tbody></table><p>The candles will print on the chart as shown in the figure below.</p><p><img src="'+m+'" alt="Candlestick Price Example.webp"></p><p>Here is a little exercise to help you understand the candlestick pattern better. Try and plot the candlesticks for the given data.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Day</th><th style="text-align:center;">Open</th><th style="text-align:center;">High</th><th style="text-align:center;">Low</th><th style="text-align:center;">Close</th></tr></thead><tbody><tr><td style="text-align:center;">Day 1</td><td style="text-align:center;">430</td><td style="text-align:center;">444</td><td style="text-align:center;">425</td><td style="text-align:center;">438</td></tr><tr><td style="text-align:center;">Day 2</td><td style="text-align:center;">445</td><td style="text-align:center;">455</td><td style="text-align:center;">438</td><td style="text-align:center;">450</td></tr><tr><td style="text-align:center;">Day 3</td><td style="text-align:center;">445</td><td style="text-align:center;">455</td><td style="text-align:center;">430</td><td style="text-align:center;">437</td></tr></tbody></table><p>Once you internalize the way candlesticks are plotted, reading the candlesticks to identify patterns becomes a lot easier.</p><p><img src="'+g+'" alt="Daily Candlestick Chart.webp"></p><p>This is how the candlestick chart looks like if you were to plot them on a time series (the above image). The green candle indicates bullishness and red indicates bearishness.</p><p>Also note, a long-bodied candle depicts strong buying or selling activity. A short-bodied candle depicts less trading activity and hence less price movement.</p><p>To sum up, candlesticks are easier to interpret in comparison to the bar chart. Candlesticks help you quickly visualize the relationship between the open and close and the high and low price points.</p><div class="tip custom-block"><p class="custom-block-title"><strong>Key takeaways from this chapter</strong></p><ol><li>Conventional chart type cannot be used for technical analysis as we need to plot 4 data points simultaneously.</li><li>A line chart can be used to interpret trends, but no other information can be derived.</li><li>Bar charts lack visual appeal, and one cannot identify patterns easily. For this reason, bar charts are not very popular.</li><li>There are two types of candlesticks – Bullish candle and Bearish candle. The structure of the candlestick, however, remains the same.</li><li>When close &gt; open = It is a Bullish candle. When close &lt; open = It is a Bearish candle.</li></ol></div><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',29)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/28clQh7CuBM",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[d("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),n(s,null,{default:h(()=>[n(i)]),_:1})])}const _=l(b,[["render",u]]);export{T as __pageData,_ as default};
